import {selectionAxes,axesText} from './lastplanner-axes.mjs';
import {PLAN_COLORS,geometryPath,scopeDrawing} from './lastplanner-map.mjs';
import {nivel} from './level.mjs';
import {executive,weekLabel,scopeProgress} from './lastplanner-cycle-model.mjs';
export async function renderCycleReport(data,filters,ctx){
 if(!data)throw Error('Carga los registros antes de generar el reporte.');
 const esc=ctx.esc,n=v=>v==null?'—':Number(v).toLocaleString('es-CL',{maximumFractionDigits:2}),report=executive(data,{level:filters.level,semana:filters.week,responsable:filters.responsable,especialidad:filters.especialidad,contratista:filters.contratista}),activities=report.activities.filter(a=>a.fase!=='borrador'),map=ctx.fondo(),root=document.createElement('section');root.className='lpCycleReport';
 const paths=[],labels=[],mismatched=[];
 activities.forEach((a,i)=>{if(a.level!==nivel.id)return;for(const scope of a.alcances){const room=ctx.rooms().find(r=>r.id===scope.roomId),source=room&&ctx.source(room);if(scope.source?.sha256&&source?.sha256!==scope.source.sha256){mismatched.push(scope.code);continue;}for(const shape of scopeDrawing(a,scope,data.restricciones)){const g=shape.geometry,path=g?geometryPath(g):ctx.path(scope.roomId);if(!path)continue;const color=PLAN_COLORS[shape.state];paths.push(`<path d="${esc(path)}" fill="${g?.type==='line'?'none':color}" fill-opacity="${shape.opacity}" fill-rule="evenodd" stroke="${color}" stroke-width="6" stroke-dasharray="${shape.dashed?'8 4':''}" vector-effect="non-scaling-stroke"/>`);}if(room){const p=ctx.position(room);labels.push(`<text x="${p[0]}" y="${p[1]}" font-size="35" fill="#000" stroke="#fff" stroke-width="2" paint-order="stroke">${i+1}</text>`);}}});
 const preview=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${map.origin[0]} ${map.origin[1]} ${map.width} ${map.height}" role="img" aria-label="Plano del piso con alcances del compromiso"><image href="${map.export||map.url}" x="${map.origin[0]}" y="${map.origin[1]}" width="${map.width}" height="${map.height}"/>${paths.join('')}${labels.join('')}</svg>`;
 root.innerHTML=`<div class="lpPrintActions"><button type="button" data-print>Imprimir / guardar PDF</button><button type="button" data-close-report>Cerrar reporte</button></div><h1>ATLAS HPC · Compromiso y ejecución semanal</h1><p>${esc(weekLabel(filters.week))} · ${esc(filters.level||'Todos los pisos')} · emisión ${esc(new Date().toLocaleString('es-CL'))}</p><p>Comprometidas: ${report.committed} · cumplidas: ${report.fulfilled} · incumplidas: ${report.failed} · por verificar: ${report.pending} · PPC: ${report.ppc==null?'Sin base':n(report.ppc)+'%'}</p><div class="lpReportPlan">${preview}</div><p>Plano: ${esc(nivel.nombre)}. Celeste: pendiente; ámbar: avance parcial; violeta: por verificar; verde: intervención verificada; rojo: bloqueo. Los trazos de ejecución corresponden a geometrías registradas expresamente; un porcentaje no inventa sus límites. Los números corresponden a las actividades de la tabla.${mismatched.length?' Fuentes cambiadas: '+esc([...new Set(mismatched)].join(', '))+'. Esas superficies requieren cotejo y no se superponen al plano actual.':''}</p><table><thead><tr><th>N° / actividad</th><th>Responsable / piso</th><th>Plazo original</th><th>Cantidad original</th><th>Ejecutado / verificado</th><th>Resultado / causa</th></tr></thead><tbody>${activities.map((a,i)=>`<tr><td>${i+1}. ${esc(a.actividad)}<small>${esc(a.recintos.map(r=>r.code).join(', '))}</small><small>Ejes: ${esc(axesText(selectionAxes(a.alcances)))}</small></td><td>${esc(a.responsable)}<small>${esc(a.level)}</small></td><td>${esc(a.compromisoOriginal?.inicioPlan||'Sin fecha histórica')} → ${esc(a.compromisoOriginal?.finPlan||'Sin fecha histórica')}</td><td>${n(a.compromisoOriginal?.cantidad)} ${esc(a.unidad)}</td><td>${n(a.cantidadEjecutada||0)} / ${n(a.verificacion.cantidadValidada)} ${esc(a.unidad)}</td><td>${esc(a.verificacion.resultado)}<small>${esc(a.verificacion.causa||'')}</small></td></tr>`).join('')}</tbody></table><h2>Restricciones y bloqueos</h2>${report.restrictions.map(r=>`<p><b>${esc(r.descripcion)}</b> · ${esc(r.estado)} · ${esc(r.responsable)} · ${esc(r.departamento||'')} · compromiso ${esc(r.compromiso||'sin fecha')}<br>${esc(r.accion||'')}</p>`).join('')||'<p>Sin restricciones vinculadas.</p>'}<h2>Asistencia diaria</h2><table><thead><tr><th>Fecha / turno</th><th>Persona</th><th>Contratista / cuadrilla</th><th>Estado / jornada</th></tr></thead><tbody>${report.attendance.map(a=>`<tr><td>${esc(a.fecha)} · ${esc(a.turno)}</td><td>${esc(a.nombre)}</td><td>${esc(a.contratista)} · ${esc(a.cuadrilla)}</td><td>${esc(a.estado)} · ${n(a.horas)} h</td></tr>`).join('')}</tbody></table><h2>Última reunión y frentes</h2>${[...data.reuniones].sort((a,b)=>b.fecha.localeCompare(a.fecha)).slice(0,1).map(r=>`<p>${esc(r.fecha)} · ${esc(r.tipo)} · ${r.asistentes.filter(a=>a.asistio).length}/${r.asistentes.length} presentes</p>${r.frentes.map(f=>`<p>${esc(f.frente)} · ${esc(f.estado)} · ${esc(f.responsable||'')} · ${n(f.dotacion)} personas</p>`).join('')}${r.acuerdos.map(a=>`<p>${esc(a.texto)} · ${esc(a.responsable||'')} · ${esc(a.plazo||'sin plazo')} · ${a.cumplido?'Cumplido':'Pendiente'}</p>`).join('')}`).join('')||'<p>Sin reuniones.</p>'}<div class="lpReportSignatures"><span>Planificación</span><span>Producción</span><span>Verificación</span></div>`;
 document.body.append(root);const close=()=>root.remove();root.querySelector('[data-close-report]').onclick=close;root.querySelector('[data-print]').onclick=()=>window.print();root.tabIndex=-1;root.focus();root.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
}
